normalization_rows.source:
projection CustomerProjection {
  source: OrderCreated
  target: CustomerView
}

consumer OrdersConsumer {
  topic: Orders
  source: OrderCreated
}

entity Customer {
  field id: UUID
  field email: String
}

index ByEmail {
  fields: [email, tenantId]
  unique: true
}

queue_deadletter OrdersPolicy {
  queue: Orders
  deadletter: OrdersDead
}

sync_outbox MobileSyncPolicy {
  changes: MobileChanges
  outbox: SyncOutbox
}

representative_families.source:
service Billing {
  api: BillingApi
  resource: Postgres
}

workflow Reconcile {
  step: load
  step: compare
}

deployment Prod {
  target: Kubernetes
  resource: Billing
}

legacy_rejections:
projection CustomerProjection from [OrderCreated] into CustomerView {
}
client BillingClient for BillingService {
}
consumer OrdersConsumer on Orders from OrderCreated {
}
sync MobileSync {
  changes MobileChanges via outbox SyncOutbox
}
